const handleMobileSend = async () => {
  if (!receivedDate || !receivedDate.toString().trim()) {
    toast.error('Defina a Data de Recebimento');
    return;
  }
  await sendCurrentListToQueue();
};

const getWizardTitle = () => {
  if (activeTab === 'method') return 'Requisição Inteligente';
  if (activeTab === 'input') return requestMode === 'manual' ? 'Selecionar produtos' : 'Colar mensagem para IA';
  if (activeTab === 'result') {
    if (isDeliveryStep) return 'Informações de Entrega';
    if (currentRequisicaoId) return 'Edite sua lista';
    if (flowSource === 'auto') return 'Revisão Requisição Automática';
    return 'Revisão da requisição';
  }
  return 'Requisição';
};

const getWizardSubtitle = () => {
  if (activeTab === 'method') return 'Escolha o método e siga as etapas';
  if (activeTab === 'input') return requestMode === 'manual' ? 'Adicione produtos e prossiga' : 'Cole a mensagem e processe com IA';
  if (activeTab === 'result') return isDeliveryStep ? 'Defina data de entrega e solicitante' : (currentRequisicaoId ? 'Edite seus itens e salve' : 'Confira os itens antes de enviar');
  return 'Monte sua requisição passo a passo';
};

const handleBack = () => {
  if (activeTab === 'method') {
    setIsLeaving(true);
    setTimeout(() => navigate('/dashboard?category=estoque'), 180);
    return;
  }

  if (activeTab === 'input') {
    setRequestMode(null);
    setActiveTab('method');
    return;
  }

  if (activeTab === 'result') {
    if (isDeliveryStep) {
      // Transição suave para voltar à revisão
      setTransitionDirection('backward');
      setIsTransitioning(true);
      setTimeout(() => {
        setIsDeliveryStep(false);
        setIsTransitioning(false);
      }, 300); // Duração da animação
      return;
    }

    // If we are in the result tab, handling depends on where we came from
    if (flowSource === 'auto') {
      // Came from wizard -> go back to method selection (or wizard if you prefer)
      // Users requested separation, so returning to method makes sense to restart
      setActiveTab('method');
      setFlowSource(null);
      setAllItems([]); // Clear items when leaving the result context
      return;
    }

    if (flowSource === 'text') {
      // Came from text input -> go back to input
      setActiveTab('input');
      return;
    }

    // Fallback default
    setActiveTab('input');
  }
};

