    {allItems.length > 0 ? (
      <div className="space-y-2">
        {allItems.map((item, idx) => (
          <div
            key={item.id}
            className="flex items-center gap-3 rounded-2xl border border-[#57715B]/10 dark:border-white/10 bg-white/60 dark:bg-black/20 backdrop-blur-md p-3"
          >
            <div className="flex-1 min-w-0">
