              {item.category && (
                <div className="text-xs text-muted-foreground">{item.category}</div>
              )}
            </div>
            <div className="flex items-center gap-2 shrink-0">
              <Input
                data-mia-field={`quantidade_manual_${item.id}`}
                type="number"
                min={0}
                value={item.requested === 0 ? '' : item.requested}
                placeholder="Qtd"
                onChange={(e) => {
                  const val = Number(e.target.value) || 0;
                  setAllItems(prev => prev.map((it, i) => i === idx ? { ...it, requested: val } : it));
                }}
                className="w-20 h-8 text-center text-sm rounded-xl border-[#57715B]/20 bg-white/80 dark:bg-black/20 focus-visible:ring-[#57715B]/30"
                aria-label={`Quantidade de ${item.name}`}
              />
              <button
                type="button"
                data-mia-skip
                onClick={() => setAllItems(prev => prev.filter((_, i) => i !== idx))}
                className="h-8 w-8 flex items-center justify-center rounded-xl text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                aria-label={`Remover ${item.name}`}
              >
                <Trash2 className="h-4 w-4" />
              </button>
            </div>
          </div>
        ))}
      </div>
    ) : (
      <div className="rounded-2xl border border-dashed border-[#57715B]/20 bg-[#57715B]/5 dark:bg-[#57715B]/10 p-8 text-center">
        <FileSpreadsheet className="h-8 w-8 text-[#57715B]/40 mx-auto mb-2" />
        <p className="text-sm text-muted-foreground">Nenhum produto adicionado ainda.</p>
        <p className="text-xs text-muted-foreground mt-1">Use o botão acima para buscar no catálogo.</p>
      </div>
    )}

    {/* Botão avançar */}
    {allItems.length > 0 && (
      <Button
        data-mia-action="ir-para-revisao-manual"
        onClick={() => setActiveTab('result')}
        disabled={allItems.every(it => it.requested === 0)}
        className="w-full gap-2 bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
      >
        <ArrowRight className="h-4 w-4" />
        Ir para revisão ({allItems.filter(it => it.requested > 0).length} com quantidade)
      </Button>
    )}
  </div>
)}
